import 'package:flutter/material.dart';
import '../core/theme/zen_colors.dart';
import '../core/widgets/zen_card.dart';
import '../core/widgets/zen_page.dart';
import '../features/view_models/feature_view_models.dart';
class OperationsScreen extends StatefulWidget { const OperationsScreen({super.key,required this.viewModel}); final OperationsViewModel viewModel; @override State<OperationsScreen> createState()=>_OperationsScreenState(); }
class _OperationsScreenState extends State<OperationsScreen>{int tab=0;@override void initState(){super.initState();widget.viewModel..addListener(_refresh)..load(tab);}@override void dispose(){widget.viewModel.removeListener(_refresh);super.dispose();}void _refresh(){if(mounted)setState((){});}@override Widget build(BuildContext c){final data=widget.viewModel.data;final title=['Meu negócio','Multiunidade','Relatórios'][tab];final items=<Widget>[if(widget.viewModel.error!=null)ZenCard(child:Text(widget.viewModel.error!))];if(tab==0){for(final barber in(data?['barbers'] as List? ?? const[])){items.add(Padding(padding:const EdgeInsets.only(bottom:10),child:ZenCard(child:ListTile(contentPadding:EdgeInsets.zero,leading:const Icon(Icons.flag,color:ZenColors.green),title:Text('${barber['name']}',style:const TextStyle(fontWeight:FontWeight.w900)),subtitle:const Text('Metas e desempenho mensal',style:TextStyle(color:ZenColors.muted))))));}}else if(tab==1){for(final unit in(data as List? ?? const[])){items.add(Padding(padding:const EdgeInsets.only(bottom:10),child:ZenCard(child:ListTile(contentPadding:EdgeInsets.zero,leading:const Icon(Icons.storefront,color:ZenColors.sky),title:Text('${unit['unit_name']}',style:const TextStyle(fontWeight:FontWeight.w900)),subtitle:Text('${unit['city']}/${unit['state']}'),trailing:ZenStatusPill(label:'${unit['status']}',color:ZenColors.gold)))));}}else{items.add(Wrap(spacing:12,runSpacing:12,children:[ZenMetricCard(icon:Icons.payments,label:'Faturamento',value:'R\$ ${((data?['revenue']as num?)??0).toStringAsFixed(2)}'),ZenMetricCard(icon:Icons.calendar_month,label:'Agendamentos',value:'${data?['appointments']??0}',color:ZenColors.sky),ZenMetricCard(icon:Icons.check_circle,label:'Finalizados',value:'${data?['completed']??0}',color:ZenColors.jade)]));}return Column(children:[Padding(padding:const EdgeInsets.fromLTRB(20,12,20,0),child:SegmentedButton<int>(segments:const[ButtonSegment(value:0,label:Text('Negócio')),ButtonSegment(value:1,label:Text('Unidades')),ButtonSegment(value:2,label:Text('Relatórios'))],selected:{tab},onSelectionChanged:(v){setState(()=>tab=v.first);widget.viewModel.load(tab);})),Expanded(child:widget.viewModel.loading?const Center(child:CircularProgressIndicator()):ZenPage(title:title,children:items))]);}}
